import random

def fast_sum(numbers):
    return sum(numbers)

# Generate a list of 2,000,000 random integers
numbers = [random.randint(-1000000, 1000000) for _ in range(2000000)]

try:
    while True:
        result = fast_sum(numbers)
        if result < 1000000:  # Check if the result is less than 100,000 to avoid infinite loop
            break
except Exception as e:
    print(f"Error: {e}")
else:
    print("Solution passed!")
